function makeActor(world, faction, x, y, hp = 30) {
  const id = world.create();
  world.add(id, Position, { x, y });
  world.add(id, Faction, { key: faction });
  world.add(id, Vitality, { maxHp: hp, hp });
  world.add(id, ActiveEffects, { effects: [] });
  return id;
}

