          const dist = rng.next() * creatureType.clusterR;
          const x = Math.round(anchor.x + Math.cos(angle) * dist);
          const y = Math.round(anchor.y + Math.sin(angle) * dist);

          const tile = getWorldTile(chunks, x, y);
