/** @type {WeakMap<object, { nextTick:number }>} */
const _stateByWorld = new WeakMap();

const HOME_IDENTITIES = new Set(["bed_home", "house_sign", "berry_bush", "herb_patch", "alchemy_bench"]);
const HOME_SOURCE_DB_AT_1_TILE = 42;
