  const id = world.create();
  world.add(id, DungeonState, { currentDepth: depth, profileType: depth === 0 ? "overworld" : "default" });
  return id;
}

function addPlayer(world, x, y) {
  const id = world.create();
  world.add(id, Player, {});
  world.add(id, Position, { x, y });
  return id;
}

function addRatatoskr(world, x, y) {
  const id = world.create();
